SET NOCOUNT ON;SET XACT_ABORT ON;CREATE TABLE #UserObject(RowId int PRIMARY KEY,Payload char(300));INSERT #UserObject SELECT RowId,CONVERT(char(300),Payload) FROM lab.SourceData;SELECT GroupKey,COUNT_BIG(*) AS ResultRows,CHECKSUM_AGG(BINARY_CHECKSUM(Payload)) ChecksumValue INTO #WorkResult FROM lab.SourceData GROUP BY GroupKey OPTION(HASH GROUP,MAXDOP 1);SELECT RowId,ROW_NUMBER() OVER(ORDER BY Payload,RowId) AS SortOrdinal INTO #SortedWork FROM lab.SourceData OPTION(MAX_GRANT_PERCENT=0.1,MAXDOP 1);INSERT lab.Evidence(Stage,UserPages,InternalPages,VersionStorePages)SELECT 'WORKLOAD',SUM(user_objects_alloc_page_count),SUM(internal_objects_alloc_page_count),(SELECT SUM(version_store_reserved_page_count) FROM tempdb.sys.dm_db_file_space_usage) FROM tempdb.sys.dm_db_task_space_usage WHERE session_id=@@SPID;IF (SELECT COUNT(*) FROM #UserObject)<>150000 OR (SELECT SUM(ResultRows) FROM #WorkResult)<>150000 OR (SELECT COUNT(*) FROM #SortedWork)<>150000 THROW 51006,'FAIL_RESULT_CONTRACT: TempDB-Workloadresultat stimmt nicht.',1;PRINT 'SQLPERF_SUMMARY|PASS|OK';
